arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for u in d['members']:
    r=u.get('profile',{}).get('email','')
    if 'ana.torre' in r.lower() or u.get('real_name','').lower().startswith('ana'):
        print(u['id'], u.get('real_name'), r, u.get('is_bot'))
"

